const UI={tabs:{},page:1,partnerPage:1,sub:'全部',color:'全部',finish:'全部',material:'',priceMax:'',partnerKind:'全部',district:'全部',trade:'全部',partnerQuery:'',ticket:'',chat:'项目群',stockQuery:'',quoteTab:'询价',projectTab:'总览'};
const MODULES={rooms:'房屋与房间',designs:'方案与交付',orders:'订单与履约',customer:'售后客服',contracts:'合同中心',changes:'变更中心',replacements:'材料替换',payments:'付款与结算',procurement:'选材与采购清单',schedule:'工期与 SOP',crew:'工种与人员',quality:'检查与整改',messages:'项目消息',members:'参与方与责任',documents:'资料中心',services:'服务与案例',inventory:'商品与库存',quotes:'询价与报价',promotion:'广告推广',analytics:'经营分析',leads:'线索与客户',finance:'企业财务',governance:'运营审核',standards:'标准与模板',history:'操作历史'};
for(const [id,name]of Object.entries(MODULES))if(!routes.some(r=>r[0]===id))routes.push([id,name]);
const NAVS={
owner:[['我的家',['home','rooms','space','designs']],['探索与选择',['market','partners','procurement']],['装修与保障',['project','orders','budget','customer','messages','preferences']]],
designer:[['设计工作',['home','leads','designs','space','procurement']],['协作交付',['partners','project','contracts','messages']],['服务经营',['services','budget','customer','preferences']]],
supplier:[['供货经营',['home','inventory','quotes','orders']],['履约与服务',['procurement','replacements','customer','messages']],['增长与账务',['promotion','analytics','budget']]],
builder:[['工程组织',['home','partners','project','schedule','crew']],['现场执行',['space','procurement','quality','changes']],['合作与结算',['contracts','budget','customer','messages']]],
inspector:[['质量工作',['home','quality','schedule','documents']],['项目协同',['project','space','messages']],['服务管理',['services','budget','customer']]],
company:[['客户与企业',['home','leads','members','analytics']],['交付统筹',['project','designs','schedule','procurement','orders','quality']],['合同与经营',['contracts','budget','finance','customer','messages']]],
admin:[['生态运营',['home','governance','inventory','partners']],['质量与规则',['standards','quality','customer']],['交易与模型',['contracts','finance','analytics','promotion','preferences','history']]]};
const ROLE_LABELS={designer:{home:'设计工作台',leads:'客户与需求',designs:'设计成果与修改',procurement:'项目材料清单',services:'设计服务与案例',budget:'设计报价与收款'},supplier:{home:'商家经营台',inventory:'商品 SKU 与库存',quotes:'询价与供货报价',orders:'发货与安装',procurement:'供货需求',budget:'供货对账'},builder:{home:'工程工作台',partners:'接单与合作',project:'我的工程',schedule:'排期与工序',crew:'工人班组',procurement:'材料与领用',quality:'验收与整改',budget:'承包与结算'},inspector:{home:'检查工作台',quality:'检查与复验',schedule:'上门日历',services:'监理服务',budget:'监理服务结算'},company:{home:'企业总览',members:'人员与职责',procurement:'采购与仓储'},admin:{home:'运营总览',preferences:'推荐模型记录',inventory:'商品资料治理'}};
const labelFor=id=>ROLE_LABELS[state.role]?.[id]||MODULES[id]||routes.find(r=>r[0]===id)?.[1]||id;
nav=function(){const groups=NAVS[state.role]||NAVS.owner;$('#nav').innerHTML=groups.map(([title,ids])=>`<div class="nav-section">${title}</div>${ids.map(id=>`<button class="nav-item ${state.view===id?'active':''}" data-route="${id}">${icon(icons[id]?id:['orders','inventory','procurement'].includes(id)?'market':['customer','messages','members','crew'].includes(id)?'partners':'project')}<span>${labelFor(id)}</span>${id==='customer'&&pendingWork().tickets?`<span class="count-badge">${pendingWork().tickets}</span>`:''}</button>`).join('')}`).join('');$('#role-name').textContent=roles[state.role].name;$('#role-name').nextElementSibling.textContent=roles[state.role].desc;$('#crumb').textContent=labelFor(state.view);};
const legacyRender=render,legacyHome=renderHome,legacySpace=renderSpace,legacyProduct=showProduct,legacyCard=productCard;
function eb(label,action,id='',value='',disabled=false){return `<button class="outline compact" data-eco="${action}" data-id="${esc(id)}" data-value="${esc(value)}" ${disabled?'disabled':''}>${label}</button>`;}
function primary(label,action,id='',value=''){return `<button class="primary compact" data-eco="${action}" data-id="${esc(id)}" data-value="${esc(value)}">${label}</button>`;}
function go(label,view){return `<button class="text-button" data-route="${view}">${label} →</button>`;}
function badge(s){return `<span class="pill ${['待核实','需整改','缺货','阻塞','待分派'].includes(s)?'warm':['完成','通过','已确认','已执行','已完成'].includes(s)?'':'purple'}">${esc(s)}</span>`;}
function table(headers,rows,empty='暂无记录'){return `<div class="table-wrap"><table class="module-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':`<div class="small-empty">${empty}</div>`}</div>`;}
function metrics(arr){return `<div class="metric-grid">${arr.map(([a,b,c])=>`<div class="metric"><span>${a}</span><strong>${b}</strong><small>${c||''}</small></div>`).join('')}</div>`;}
function tabs(key,values){let current=UI.tabs[key]||values[0];return `<div class="module-tabs">${values.map(v=>`<button class="${v===current?'active':''}" data-eco="tab" data-id="${key}" data-value="${v}">${v}</button>`).join('')}</div>`;}
function detailCells(obj){return `<div class="detail-grid">${Object.entries(obj).map(([k,v])=>`<div class="detail-cell"><small>${esc(k)}</small><b>${esc(v??'待核实')}</b></div>`).join('')}</div>`;}
function evidence(list){return `<div class="evidence-list">${(list||[]).map(e=>`<div class="evidence-item">${e.data?.startsWith('data:image/')?`<img src="${e.data}" alt="${esc(e.name)}">`:''}${esc(e.name)}<small>${esc(e.date||'')}</small></div>`).join('')}</div>`;}
function pagination(total,page,kind,size=12){const max=Math.max(1,Math.ceil(total/size));return `<div class="pagination">${eb('上一页',kind,'',String(Math.max(1,page-1)),page<=1)}<span>${page} / ${max} · 共 ${total} 条</span>${eb('下一页',kind,'',String(Math.min(max,page+1)),page>=max)}</div>`;}
function contextBar(){const p=currentProject();return `<div class="workspace-context"><label>当前项目 <select id="eco-project" aria-label="切换项目">${E.projects.map(r=>`<option value="${r.id}" ${r.id===p.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><div class="context-meta"><span>${esc(p.district)} · ${esc(p.scope)}</span><span>责任方：${esc(p.main)}</span><a href="#members">查看责任与权限 ↗</a></div></div>`;}
function moduleIntro(eye,title,sub,buttons=''){return intro(eye,title,sub,buttons);}
function permitted(id){return ['home','project','space','market','partners','assets','budget','preferences','rooms','designs','procurement','orders','contracts','changes','replacements','payments','schedule','quality','customer','messages','members','documents','history'].includes(id)||NAVS[state.role].some(g=>g[1].includes(id));}
const newViews={rooms:renderRooms,designs:renderDesigns,orders:renderOrders,customer:renderCustomer,contracts:renderContracts,changes:renderChanges,replacements:renderReplacements,payments:renderPayments,procurement:renderProcurement,schedule:renderSchedule,crew:renderCrew,quality:renderQuality,messages:renderMessages,members:renderMembers,documents:renderDocuments,services:renderServices,inventory:renderInventory,quotes:renderQuotes,promotion:renderPromotion,analytics:renderAnalytics,leads:renderLeads,finance:renderFinance,governance:renderGovernance,standards:renderStandards,history:renderHistory};
render=function(){if(!permitted(state.view)){state.view='home';}if(newViews[state.view]){nav();document.body.classList.remove('menu-open','studio-full');$('#space-page').hidden=true;$('#content').hidden=false;$('#content').innerHTML=`<div class="page-enter">${newViews[state.view]()}</div>`;updateCompare();}else legacyRender();let host=state.view==='space'?$('#space-page'):$('#content');host.querySelector('.workspace-context')?.remove();host.insertAdjacentHTML('afterbegin',contextBar());let c=E.messages.filter(m=>m.project===E.activeProject&&m.roles.includes(state.role)&&!m.read.includes(state.role)).length;let msg=$('[data-action="notifications"]');msg.querySelector('.global-notification-count')?.remove();if(c)msg.insertAdjacentHTML('beforeend',`<span class="global-notification-count">${c}</span>`);};
renderHome=function(){if(state.role!=='owner')return renderDistinctHome();return legacyHome()+`<section style="margin-top:26px"><div class="section-head"><div><h2>交付有负责人，售后有入口</h2><p>问题、费用和变更，在同一份项目记录中处理。</p></div>${go('售后客服','customer')}</div><div class="service-center-cards"><button data-route="orders"><strong>▣</strong>我的订单<small>${pendingWork().orders} 个履约中</small></button><button data-route="changes"><strong>⇄</strong>待确认变更<small>${pendingWork().changes} 个待处理</small></button><button data-route="quality"><strong>✓</strong>检查与验收<small>${pendingWork().checks} 个待闭环</small></button><button data-route="customer"><strong>♡</strong>售后与客服<small>${pendingWork().tickets} 个处理中</small></button></div></section>`;};
function renderDistinctHome(){let role=state.role,p=currentProject();let head=moduleIntro('A WORKSPACE THAT WORKS',roles[role].heading,roles[role].sub,role==='supplier'?primary('＋ 新增商品','product-edit'):role==='designer'?primary('＋ 新建设计成果','design-new'):role==='builder'?primary('＋ 施工记录','task-log'):role==='inspector'?primary('＋ 新建检查','check-new'):role==='company'?primary('＋ 新客户','lead-new'):go('审核队列','governance'));let body='';
if(role==='designer')body=metrics([['客户需求',E.leads.length,'咨询、量房与跟进'],['待确认成果',projectRows('designs').filter(d=>d.state==='待业主确认').length,'业主确认后交底'],['已选材料',state.selected.length,'规格、数量与交期'],['设计服务',E.services.filter(s=>s.role==='designer').length,'套餐与交付范围']])+`<div class="two-cols"><section class="panel"><div class="section-head"><h2>设计交付队列</h2>${go('全部成果','designs')}</div>${projectRows('designs').map(d=>`<div class="todo"><span class="avatar">设</span><span><b>${esc(d.name)}</b><small>${esc(d.kind)} · ${esc(d.state)}</small></span><button class="text-button" data-eco="design-detail" data-id="${d.id}">处理 →</button></div>`).join('')}<div class="button-row" style="margin-top:15px">${go('查看客户需求','leads')}${go('整理材料','procurement')}</div></section><section class="panel"><h2>设计落地检查</h2><div class="check-list"><p>① 尺寸是否现场复核</p><p>② 商品是否具备可采购规格</p><p>③ 工艺、铺法和交底是否明确</p><p>④ 谁确认修改，谁承担后续工作</p></div>${go('进入方案与三维','space')}</section></div>`;
if(role==='supplier')body=metrics([['商品 SKU',products.length,'20 大类 · 多规格'],['待回复询价',E.inquiries.filter(q=>q.state==='待回复').length,'先确认交期与费用'],['待履约订单',projectRows('orders').filter(o=>o.state!=='完成').length,'供货、安装与售后'],['缺货 SKU',products.filter(p=>p.stock===0).length,'可以提出替代品']])+`<div class="two-cols"><section class="panel"><div class="section-head"><h2>优先处理的供货事项</h2>${go('询价中心','quotes')}</div>${projectRows('orders').map(o=>`<div class="todo"><span class="avatar">货</span><span><b>${esc(productBy(o.product)?.name)}</b><small>${o.id} · ${o.state} · ${o.scheduled}</small></span><button class="text-button" data-eco="order-detail" data-id="${o.id}">处理 →</button></div>`).join('')}</section><section class="panel"><h2>商品与经营</h2><div class="object-list" style="margin-top:15px">${[['SKU、库存与交期','inventory'],['订单配送与安装','orders'],['推广投放与审核','promotion'],['供货对账与应收','budget']].map(([n,r])=>`<button class="single-source-link" data-route="${r}">${n}<span>→</span></button>`).join('')}</div></section></div>`;
if(role==='builder')body=metrics([['当前工程',E.projects.length,'按项目独立管理'],['未完成工序',projectRows('tasks').filter(t=>t.state!=='完成').length,'前置与材料条件'],['工人班组',E.crew.length,'12 类工种'],['待整改',projectRows('checks').filter(c=>c.state==='需整改').length,'补证、复验后闭环']])+`<div class="panel"><div class="section-head"><h2>现场工序看板</h2>${go('完整排期','schedule')}</div>${taskBoard()}</div><div class="work-grid">${[['材料到了吗','procurement','领料、短缺、补料和退料'],['人员排好了吗','crew','按工种和日期组织班组'],['异常先确认','changes','增项、返工、工期影响']].map(([a,b,c])=>`<div class="panel"><h3>${a}</h3><p class="subtext">${c}</p>${go('进入处理',b)}</div>`).join('')}</div>`;
if(role==='inspector')body=metrics([['待检查',projectRows('checks').filter(c=>c.state==='待检查').length,'先核对资料'],['待整改',projectRows('checks').filter(c=>c.state==='需整改').length,'责任人与期限'],['待复验',projectRows('checks').filter(c=>c.state==='待复验').length,'核查整改证据'],['检查类别',Object.keys(C.checklists).length,'项目约定标准']])+`<div class="panel"><div class="section-head"><h2>检查与复验队列</h2>${go('质量中心','quality')}</div>${checkTable()}</div><div class="two-cols" style="margin-top:20px"><div class="panel"><h3>证据先于结论</h3><p class="subtext">记录检查项、位置、实测值、依据与照片。资料缺失时标为待核实，不自动判定通过。</p>${go('查看项目资料','documents')}</div><div class="panel"><h3>上门与报告</h3><p class="subtext">预约、记录、整改、复验和报告共用一条检查记录。</p>${go('上门日历','schedule')}${go('服务与范围','services')}</div></div>`;
if(role==='company')body=metrics([['客户线索',E.leads.length,'分配、跟进与转化'],['统筹项目',E.projects.length,'设计、采购与工程'],['待签合同',E.contracts.filter(c=>c.state!=='已确认').length,'范围与付款条件'],['未结售后',E.tickets.filter(t=>t.state!=='已完成').length,'主要承接方组织处理']])+`<div class="two-cols"><div class="panel"><div class="section-head"><h2>经营到交付</h2>${go('客户管理','leads')}</div>${['线索 → 需求 → 报价 → 项目','设计 → 采购 → 施工 → 验收','合同 → 付款 → 对账 → 售后'].map(t=>`<div class="todo"><b>${t}</b></div>`).join('')}</div><div class="panel"><h2>企业待办</h2><div class="object-list" style="margin-top:15px">${[['内部审核与责任分工','members'],['预算及费用待核实','budget'],['采购与仓储','procurement'],['应收应付及报表','finance']].map(([n,r])=>`<button class="single-source-link" data-route="${r}">${n}<span>→</span></button>`).join('')}</div></div></div>`;
if(role==='admin')body=metrics([['入驻待审',E.applications.filter(a=>a.state==='待审核').length,'补充资料、通过或退回'],['示例服务档案',people.length,'分角色与区域'],['待协调售后',E.tickets.filter(t=>t.disputed).length,'查看证据与记录'],['操作记录',E.audits.length,'按角色和项目追溯']])+`<div class="two-cols"><div class="panel"><h2>运营审核队列</h2>${applicationTable()}</div><div class="panel"><h2>治理入口</h2><div class="object-list" style="margin-top:15px">${[['合同、SOP 与质量标准','standards'],['推荐与广告策略','analytics'],['投诉与争议协调','customer'],['权限及操作记录','history']].map(([n,r])=>`<button class="single-source-link" data-route="${r}">${n}<span>→</span></button>`).join('')}</div></div></div>`;
return head+body+`<section style="margin-top:27px"><div class="section-head"><h2>项目工作区</h2>${go('查看完整项目','project')}</div><div class="role-projects">${E.projects.map(x=>`<div class="role-project-row"><span class="avatar">⌂</span><div><h3>${esc(x.name)}</h3><small>${esc(x.scope)} · ${esc(x.stage)} · ${esc(x.main)}</small></div><div class="button-row">${badge(x.id===p.id?'当前项目':x.stage)}${eb('进入项目','activate',x.id)}</div></div>`).join('')}</div></section>`;}
let marketCache={key:'',list:[]};
renderMarket=function(){let list=products.filter(p=>p.status==='上架'&&(category==='全部'||p.cat===category)&&(UI.sub==='全部'||p.sub===UI.sub)&&(roomFilter==='全部空间'||p.room.includes(roomFilter))&&(!query||(p.name+p.spec+p.tags.join('')+p.cat+p.sub+p.material).includes(query))&&(!onlyStock||p.stock>0&&p.delivery<=7)&&(UI.color==='全部'||p.color===UI.color)&&(UI.finish==='全部'||p.finish===UI.finish)&&(!UI.priceMax||p.price<=Number(UI.priceMax)));if(sort==='low')list.sort((a,b)=>a.price-b.price);else if(sort==='delivery')list.sort((a,b)=>a.delivery-b.delivery);else{let key=JSON.stringify([list.map(p=>p.id),state.events.length,state.events.filter(e=>e.retracted).length,state.deletedTags,state.personalized,state.modelOn,roomFilter,E.strategy.version]);if(key!==marketCache.key){marketCache={key,list:rank(list)};}list=marketCache.list;}let max=Math.max(1,Math.ceil(list.length/12));UI.page=Math.min(UI.page,max);let cats=[...new Set(products.map(p=>p.cat))],subs=category==='全部'?[]:[...new Set(products.filter(p=>p.cat===category).map(p=>p.sub))];return moduleIntro('MATERIALS, WITH EVERY DETAIL','让每种喜欢，都有具体的规格','按房间、品类与规格挑选。价格、库存和交期均为交互示例，正式采购需核实。',`<button class="outline compact" data-route="procurement">方案清单 ${state.selected.length}</button>`)+`<div class="catalog-layout"><aside class="catalog-categories"><button class="${category==='全部'?'active':''}" data-eco="catalog-cat" data-value="全部">全部好物 <small>${products.length}</small></button>${cats.map(c=>`<button class="${category===c?'active':''}" data-eco="catalog-cat" data-value="${c}">${c}<small>${products.filter(p=>p.cat===c).length}</small></button>`).join('')}</aside><section><div class="module-search"><form id="eco-search"><input name="query" value="${esc(query)}" placeholder="搜索名称、材质、规格、花纹" aria-label="搜索商品"><button class="outline compact">搜索</button></form><select id="eco-sort" aria-label="排序"><option value="recommend" ${sort==='recommend'?'selected':''}>老虎机推荐</option><option value="low" ${sort==='low'?'selected':''}>单价从低到高</option><option value="delivery" ${sort==='delivery'?'selected':''}>交期优先</option></select></div><div class="module-search"><select id="eco-room" aria-label="商品适用房间">${['全部空间',...C.rooms].map(r=>`<option ${r===roomFilter?'selected':''}>${r}</option>`).join('')}</select><select id="eco-color" aria-label="商品色系">${['全部',...C.colors].map(v=>`<option value="${v}" ${UI.color===v?'selected':''}>${v==='全部'?'全部色系':v}</option>`).join('')}</select><select id="eco-finish" aria-label="表面工艺">${['全部',...C.finishes].map(v=>`<option value="${v}" ${UI.finish===v?'selected':''}>${v==='全部'?'全部表面':v}</option>`).join('')}</select><input id="eco-price-max" type="number" min="0" value="${UI.priceMax}" placeholder="最高单价" aria-label="最高单价">${eb(onlyStock?'✓ 现货且7天内':'现货且7天内','stock-filter')}${eb('清除条件','catalog-reset')}</div><div class="subcat-chips">${subs.length?['全部',...subs].map(s=>`<button class="${UI.sub===s?'active':''}" data-eco="sub" data-value="${s}">${s}</button>`).join(''):''}</div><div class="section-head"><span class="label-muted">${list.length} 个匹配 SKU · ${roomFilter} · 每页 12 个</span>${go('偏好与学习记录','preferences')}</div><div class="card-grid">${list.slice((UI.page-1)*12,UI.page*12).map(productCard).join('')}</div>${!list.length?`<div class="panel empty">没有符合所有条件的商品。${eb('清除筛选','catalog-reset')}${eb('登记选材需求','custom-inquiry')}</div>`:''}${pagination(list.length,UI.page,'catalog-page')}${renderAd()}${learningStrip()}</section></div>`;};
productCard=function(p){let result=legacyCard({...p,name:esc(p.name),spec:esc(p.spec)});return result.replace('<p>'+esc(p.spec)+'</p>',`<p>${esc(p.spec)}</p><p>${esc(p.color)} · ${esc(p.texture)} · ${p.stock>0?'可询价':'缺货可找替代'}</p>`);};
showProduct=function(id){let p=productBy(id);if(!p)return;let siblings=products.filter(x=>x.cat===p.cat&&x.sub===p.sub).slice(0,9);modal(p.name,`${slot(p.image,'1200 × 900 · 4:3',p.tone)}<div class="price-line"><span class="price">¥${money(p.price)}<small> / ${p.unit}</small></span>${badge(p.stock>0?'可询价':'缺货')}</div><div class="switch-pills">${siblings.map(x=>`<button data-eco="product-variant" data-id="${x.id}" class="${x.id===p.id?'active':''}">${esc(x.spec)} · ${esc(x.color)}</button>`).join('')}</div>${detailCells({'品牌 / 商家':p.vendor,'SKU':p.sku,'规格':p.spec,'颜色 / 花纹':p.color+' / '+p.texture,'材质':p.material,'表面':p.finish,'适用房间':p.room.join('、'),'库存 / 交期':p.stock+' '+p.unit+' / '+p.delivery+' 天（示例）','包装换算':p.pack+' '+p.unit+' / 包装（需核实）','批次':p.batch,'配送':p.deliveryArea+' · 示例运费 ¥'+p.shipping,'安装与质保':p.installation+'；'+p.warranty})}<div class="inline-warning">颜色、性能、检测和质保资料需真实商家补齐。示意模型不代表已关联真实商品；定制及施工用途需专业确认。</div><div class="button-row">${eb('加入指定房间','place-product',p.id)}${eb('申请样品','sample',p.id)}${eb('咨询商家','consult-product',p.id)}${eb('询价','create-inquiry',p.id)}${primary('创建模拟订单','order-new',p.id)}</div><div class="button-row" style="margin-top:10px"><button class="outline compact" data-action="favorite" data-id="${p.id}">收藏</button><button class="outline compact" data-action="compare" data-id="${p.id}">加入对比</button><button class="outline compact" data-action="feedback" data-id="${p.id}">纠正推荐</button></div>`,true);};
renderPartners=function(){let list=people.filter(p=>(UI.partnerKind==='全部'||p.role===UI.partnerKind)&&(UI.district==='全部'||p.district===UI.district)&&(UI.trade==='全部'||p.trade===UI.trade)&&(!UI.partnerQuery||(p.name+p.tags.join('')+p.about).includes(UI.partnerQuery)));let page=UI.partnerPage=Math.min(UI.partnerPage,Math.max(1,Math.ceil(list.length/12)));return moduleIntro('THE RIGHT PEOPLE, THE RIGHT WORK','各有专业，一起交付','设计、施工、单工种、材料、定制与监理。示例档案不代表真实入驻或已认证。',primary('＋ 发布合作需求','need-new'))+`<div class="module-search"><form id="partner-search"><input name="q" value="${esc(UI.partnerQuery)}" placeholder="搜索姓名、风格、能力" aria-label="搜索服务伙伴"><button class="outline compact">搜索</button></form><select id="partner-kind" aria-label="伙伴类型">${['全部','设计师','设计工作室','装修公司','施工队','工人','材料商','定制商','监理'].map(x=>`<option ${x===UI.partnerKind?'selected':''}>${x}</option>`).join('')}</select><select id="partner-district" aria-label="伙伴地区">${['全部',...districts].map(x=>`<option ${x===UI.district?'selected':''}>${x}</option>`).join('')}</select><select id="partner-trade" aria-label="工种">${['全部',...C.trades].map(x=>`<option ${x===UI.trade?'selected':''}>${x}</option>`).join('')}</select></div><p class="metric-note">${list.length} 个匹配档案 · 服务区域先公开，详细项目地址合作授权后查看。</p><div class="work-grid">${list.slice((page-1)*12,page*12).map(p=>`<article class="work-card">${slot(p.image,'1200 × 900 · 4:3',p.tone)}<div class="work-card-body"><div class="summary-title"><h3>${esc(p.name)}</h3>${badge(p.role)}</div><p>${esc(p.title)}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="meta-line"><span>${esc(p.range)}</span><span>${p.team||1} 人</span></div><p>${esc(p.available||'可登记预约')} · ${esc(p.fee)}</p><div class="button-row">${eb('服务详情','partner-view',p.id)}${eb('邀请报价','invite-partner',p.id)}</div></div></article>`).join('')}</div>${pagination(list.length,page,'partner-page')}`;};
function renderAd(){let ad=E.ads.find(a=>a.state==='已通过'&&a.area===currentProject().city&&a.start<=TODAY&&a.end>=TODAY&&!E.adHidden.includes(a.id)&&productBy(a.product)?.stock>0&&productBy(a.product)?.status==='上架'&&(roomFilter==='全部空间'||productBy(a.product).room.includes(roomFilter)));if(!ad)return '';let p=productBy(ad.product);return `<div class="module-banner"><span class="ad-label">推广</span><div><h3>${esc(p.name)}</h3><p>${esc(p.vendor)} · 按当前服务区域展示${E.adPersonalized?'，不绕过适用条件':''}</p></div><div class="button-row">${eb('查看商品','product-variant',p.id)}${eb('为什么看到','ad-why',ad.id)}${eb('隐藏','ad-hide',ad.id)}</div></div>`;}
function renderRooms(){let p=currentProject(),rooms=projectRows('rooms');return moduleIntro('THE HOME BEFORE THE PLAN','从房屋，到每一个使用空间','保留原图、识别值与实测依据。房间分类和尺寸校正不等于结构安全鉴定。',eb('编辑房屋档案','house-edit')+primary('＋ 添加房间','room-edit'))+tabs('rooms',['房间档案','房屋信息','需求与生活'])+(UI.tabs.rooms==='房屋信息'?`<div class="panel">${detailCells({'房屋名称':p.name,'房屋类型':p.type,'城市 / 区域':p.city+' / '+p.district,'房屋情况':p.condition,'建筑面积':p.area+' ㎡','楼层数':p.floors,'详细地址':can('owner','company')||E.permissions.address?p.address:'仅展示服务区域，详细地址待授权','主要交付责任方':p.main,'计划开工':p.start,'期望完工':p.end})}<div class="notice">房屋档案和三维模块目前独立维护；修改平台档案不会擅自修改原三维几何。</div>${['复式','跃层','别墅','自建房'].includes(p.type)?'<div class="hint-box">已启用多楼层资料范围：可为房间注明楼层，并补充楼梯、庭院和设备资料。</div>':''}</div>`:UI.tabs.rooms==='需求与生活'?`<div class="panel">${detailCells({'装修范围':p.scope,'装修目的':p.purpose,'常住人数':p.residents,'风格偏好':p.style,'目标预算':'¥'+money(p.budget),'需要服务':p.services||'设计、施工、材料与监理待确认','现场条件':p.conditions||'电梯、搬运、施工时间待核实','已有合作方':p.main})}${primary('完善装修需求','requirements-edit')}${go('资料中心','documents')}</div>`:`<div class="work-grid">${rooms.map(r=>`<article class="work-card"><div class="work-card-body"><div class="summary-title"><h3>${esc(r.name)}</h3>${badge(r.verified?'已复核':'待复核')}</div><p>${esc(r.type)} · ${esc(r.zone)}</p><div class="room-dimensions"><span>长 ${r.length} m</span><span>宽 ${r.width} m</span><span>高 ${r.height} m</span><span>地面 ${(r.length*r.width).toFixed(2)} ㎡</span></div><p>来源：${esc(r.source)} · ${esc(r.note)}</p><div class="button-row">${eb('尺寸与校正','room-edit',r.id)}${eb('查看依据','room-history',r.id)}${eb('生成选购清单','room-shopping',r.id)}${eb('标记复核','room-verify',r.id)}</div></div></article>`).join('')}</div>`);}
function renderDesigns(){let ds=projectRows('designs'),vs=projectRows('versions');return moduleIntro('DESIGN THAT CAN BE DELIVERED',can('designer')?'设计成果与交底':'我的方案中心','候选、确认和执行版本分开。修改保留历史，不覆盖已签合同与订单。',can('designer','company')?primary('＋ 提交设计成果','design-new'):go('打开三维','space'))+tabs('designs',['设计成果','方案版本','材料与对象'])+(UI.tabs.designs==='方案版本'?table(['方案','状态','日期','选品','操作'],vs.map(v=>[esc(v.name),badge(v.state),v.created,(v.selected||[]).length+' 件',`<div class="row-actions">${eb('详情与比较','version-view',v.id)}${eb('复制','version-copy',v.id)}${eb('重命名','version-rename',v.id)}${eb('设为候选','version-state',v.id,'候选')}${eb('提交确认','version-state',v.id,'待确认')}${eb('设为执行版','version-state',v.id,'执行版')}${eb('恢复选品','version-restore',v.id)}</div>`])):UI.tabs.designs==='材料与对象'?renderPlanItems(true):`<div class="work-grid">${ds.map(d=>`<article class="work-card">${slot('方案效果图或图纸预览','1200 × 900 · 4:3','slot-lilac')}<div class="work-card-body"><div class="summary-title"><h3>${esc(d.name)}</h3>${badge(d.state)}</div><p>${esc(d.kind)} · 可修改 ${d.revisions} 次（约定示例）</p><p>${esc(d.description)}</p><div class="button-row">${eb('查看与讨论','design-detail',d.id)}${can('owner')?eb('确认成果','design-approve',d.id):''}${can('designer','company')?eb('提交新版本','design-revise',d.id)+eb('发布交底','design-handover',d.id):''}</div></div></article>`).join('')}${!ds.length?'<div class="panel small-empty">当前项目尚无设计成果，可由设计师提交。</div>':''}</div>`);}
function renderPlanItems(compact=false){ensureItems();let rows=planItems();return `<div class="section-head"><h3>房间与商品对应清单</h3>${go('继续选材','market')}</div>${table(['房间 / 位置','商品 / 状态','工程量','依据','操作'],rows.map(i=>{let p=productBy(i.product);return [esc(i.room)+'<small>'+esc(i.position||'使用位置待补充')+'</small>',esc(p.name)+'<small>'+esc(p.spec)+'</small>'+badge(i.status),i.qty+' '+p.unit+'<small>损耗 '+(i.loss===null?'待核实':i.loss+'%')+' · 包装 '+p.pack+'</small>',esc(i.source)+'<small>'+(i.verified?'已复核':'待核实，不作正式工程量')+'</small>',`<div class="row-actions">${eb('修改数量与房间','item-edit',i.id)}${eb('材料属性','product-variant',p.id)}${eb('询价','create-inquiry',p.id)}${!compact?eb('模拟采购','order-from-item',i.id):''}${eb('移除','item-remove',i.id)}</div>`];}),'还没有选品。去商城将商品加入指定房间。')}`;}
function renderProcurement(){let tab=UI.tabs.procurement||'房间清单';return moduleIntro('MATERIALS, FROM CHOICE TO SITE',can('builder')?'领料与材料计划':can('supplier')?'项目供货需求':'选材与采购清单','工程量、来源、包装和进场时间都留有依据。',eb('批量询价','bulk-inquiry')+primary('保存方案快照','plan-snapshot'))+tabs('procurement',['房间清单','采购进度','领料与仓储'])+(tab==='采购进度'?table(['商品','订单','到场计划','状态','下一步'],projectRows('orders').map(o=>[esc(productBy(o.product)?.name),o.id,o.scheduled,badge(o.state),eb('查看履约','order-detail',o.id)])):tab==='领料与仓储'?`<div class="panel"><div class="section-head"><h3>材料流转记录</h3>${can('builder','company','supplier')?primary('＋ 登记领用 / 退料','stock-move'):''}</div>${table(['类型','材料','数量','经办角色','说明'],E.stockMoves.filter(m=>m.project===E.activeProject).map(m=>[esc(m.kind),esc(m.name),m.qty+' '+esc(m.unit),roles[m.role]?.name||m.role,esc(m.note)]))}<div class="inline-warning">领料前需完成材料清单审核；库存变化和人员责任通过记录关联，不替代实际仓库管理。</div></div>`:renderPlanItems());}
renderProject=function(){let p=currentProject(),pending=pendingWork();const tabsMap=[['总览','project'],['需求','rooms'],['房屋与模型','space'],['方案','designs'],['参与方','members'],['报价','budget'],['合同','contracts'],['订单','orders'],['施工计划','schedule'],['材料','procurement'],['质量验收','quality'],['资金','payments'],['变更','changes'],['消息','messages'],['售后','customer'],['资料','documents'],['历史','history']];return moduleIntro('ONE PROJECT, SHARED RESPONSIBILITY',esc(p.name),'同一份项目记录，多方分别承担职责。功能入口唯一，项目页负责串联。',eb('选择其他项目','project-list')+primary('＋ 发起变更','change-new'))+`<div class="project-tabs">${tabsMap.map(([n,r])=>`<button data-route="${r}">${n}</button>`).join('')}</div>`+metrics([['当前阶段',esc(p.stage),'以实际确认推进'],['待确认变更',pending.changes,'先确认再执行'],['履约订单',pending.orders,'供货、配送与安装'],['未结售后',pending.tickets,'统一入口，明确处理人']])+`<div class="two-cols"><section class="panel"><div class="section-head"><h2>交付责任</h2>${go('分工与报酬','members')}</div>${detailCells({'主要交付责任方':p.main,'业主代表':p.representative,'项目范围':p.scope,'目标预算':'¥'+money(p.budget)})}<p class="subtext">出现问题由主要承接方组织设计、供货、施工相关方处理；平台提供协调与证据记录。</p>${go('联系负责人','customer')}</section><section class="panel"><div class="section-head"><h2>当前关键任务</h2>${go('完整施工计划','schedule')}</div>${projectRows('tasks').slice(0,4).map(t=>`<div class="todo"><span><b>${esc(t.name)}</b><small>${esc(t.person)} · ${t.state} · ${taskReady(t)?'前序已满足':'等待前序'}</small></span><button class="text-button" data-eco="task-detail" data-id="${t.id}">查看 →</button></div>`).join('')}</section></div><div class="two-cols" style="margin-top:20px"><section class="panel"><h2>近期项目动态</h2>${E.messages.filter(m=>m.project===p.id&&m.roles.includes(state.role)).slice(0,5).map(m=>`<div class="todo"><span><b>${esc(m.text)}</b><small>${esc(m.time.slice(0,10))}</small></span>${go('查看',m.link)}</div>`).join('')}</section><section class="panel"><h2>资料、版本与保障</h2><div class="object-list" style="margin-top:15px">${[['确认方案与图纸','designs'],['合同与付款条件','contracts'],['材料替代与差异','replacements'],['售后与质保','customer']].map(([n,r])=>`<button class="single-source-link" data-route="${r}">${n}<span>→</span></button>`).join('')}</div></section></div>`;};
function renderMembers(){let p=currentProject();return moduleIntro('RESPONSIBILITY BEFORE WORK','谁负责，谁确认，先说清楚','业主有统一入口；服务内容、报酬与权限在合作前明确。',primary('＋ 邀请参与方','member-new'))+tabs('members',['角色与责任','服务报酬','地址与项目授权'])+(UI.tabs.members==='服务报酬'?`<div class="notice">报酬是内部合作约定示例；只展示当前角色相关项。平台不能承诺隐藏利益信息后就解决全部冲突。</div>${table(['服务','收款方','依据','金额','状态','操作'],projectRows('remuneration').filter(r=>can('company','admin')||can('designer')&&r.service==='设计服务'||can('builder')&&r.service==='施工管理'||can('owner')&&r.service==='设计服务').map(r=>[r.service,esc(r.payee),esc(r.basis),'¥'+money(r.amount),badge(r.state),can('company')?eb('确认或调整','fee-edit',r.id):'按对应合同约定']))}${can('company')?primary('＋ 增加报酬约定','fee-edit'):''}`:UI.tabs.members==='地址与项目授权'?`<div class="panel">${detailCells({'公开服务区域':p.city+' / '+p.district,'详细地址':can('owner','company')||E.permissions.address?p.address:'未授权，不展示','授权范围':E.permissions.address?'项目协作方（演示）':'仅业主与主要承接方'})}<p class="subtext">目前为浏览器演示权限，不具备后端安全隔离。真实部署需由服务端执行项目授权。</p>${can('owner','company')?eb(E.permissions.address?'撤销协作地址授权':'授权协作方查看地址','address-toggle'):''}</div>`:`<div class="panel"><div class="summary-title"><h3>主要交付责任方：${esc(p.main)}</h3>${can('owner','company')?eb('移交负责人','main-edit'):''}</div>${table(['成员','角色','负责范围','操作'],p.members.map((m,i)=>[esc(m.name),roles[m.role]?.name||esc(m.role),esc(m.duty),can('owner','company')?`<div class="row-actions">${eb('调整职责','member-edit',i)}${i>0?eb('移出项目','member-remove',i):''}</div>`:'查看授权范围']))}</div>`);}
function renderDocuments(){let fs=projectRows('files');return moduleIntro('FILES THAT STAY WITH THE HOME','项目资料与交付档案','图纸、照片、合同附件、验收与维保资料，按版本留存。',primary('＋ 上传资料','file-new'))+table(['文件','分类','版本 / 来源','操作'],fs.map(f=>[esc(f.name),esc(f.kind),'V'+f.version+' / '+esc(f.source),`<div class="row-actions">${eb('查看','file-view',f.id)}${f.data?eb('下载','file-download',f.id):''}${eb('补充新版本','file-revise',f.id)}</div>`]))+`<div class="module-help">图片和小文件可存入本地演示，单个文件限制 500 KB；大文件需后续接入文件服务。不上传真实敏感资料。</div>`;}
const legacyBudget=renderBudget;
renderBudget=function(){let tab=UI.tabs.budget||'费用清单',p=currentProject();let head=moduleIntro('CLEAR COSTS, CLEAR AGREEMENTS',can('supplier')?'供货报价与对账':can('builder')?'施工承包与结算':can('designer')?'设计报价与收款':'预算与账单','同笔交易双方金额一致。内部采购价、承包价与对客价按单据区分。',eb('调整目标预算','budget-edit')+primary('申请核价','quote-request'))+tabs('budget',['费用清单','付款与结算','未核实与漏项']);if(tab==='付款与结算')return head+renderPayments(true);if(tab==='未核实与漏项')return head+`<div class="panel"><h2>需要确认的费用与条件</h2><div class="check-list">${['尺寸和工程量尚未现场复核','配送、上楼、搬运条件','拆除后基层修复','定制复尺、加工和收口','材料损耗、补料与余料','安装是否与施工项重复','未列设备、税费及质保范围'].map(t=>`<label><input type="checkbox"> ${t}</label>`).join('')}</div>${eb('生成核价事项','quote-request')}${go('查看合同未包含项','contracts')}</div>`;
let rows=can('supplier')?projectRows('orders').map(o=>[productBy(o.product)?.name,o.qty+' '+productBy(o.product)?.unit,o.price,o.qty*o.price,o.vendor,o.state]):can('builder')?[['施工人工与承包范围','1 项',32000,32000,'按施工合同','待确认']]:can('designer')?[['设计服务及交底','108 ㎡',180,19440,'按设计合同','待确认']]:can('inspector')?[['监理服务','1 项',4000,4000,'按监理合同','待确认']]:budgetItems.map(r=>[r[0],r[2]+' '+r[4],r[3],r[5],r[1],r[6]]);return head+metrics([['目标预算','¥'+money(p.budget),'目标可调整'],['已确认合同','¥'+money(E.contracts.filter(c=>c.project===p.id&&c.state==='已确认').reduce((s,c)=>s+c.amount,0)),'模拟合同确认记录'],['已执行变更',(approvedChangeTotal()>=0?'+':'')+'¥'+money(approvedChangeTotal()),'仅已确认执行项'],['已付节点款','¥'+money(paidTotal()),'模拟付款，无资金流动']])+table(['费用','工程量','单价','金额','范围','状态'],rows.map(([a,b,c,d,e,f])=>[esc(a),esc(b),'¥'+money(c),'¥'+money(d),esc(e),badge(f)]))+`<div class="notice">估算、报价、合同和结算不同。未核实项不填零；清单商品可能与基础报价重叠，核价前需去重。</div>${renderPlanItems(true)}`;};
const ORDER_STEPS=['待确认','待付款','备货中','生产中','待发货','配送中','待签收','待安装','待验收','完成'];
function orderTotal(o){return Math.round((o.price*o.qty+Number(o.shipping||0))*100)/100;}
function renderOrders(){let tab=UI.tabs.orders||'全部',list=projectRows('orders').filter(o=>tab==='全部'||tab==='待处理'&&!['完成','已取消'].includes(o.state)||tab==='已完成'&&o.state==='完成'||tab==='异常与售后'&&E.tickets.some(t=>t.order===o.id));return moduleIntro('FROM ORDER TO HOME',can('supplier')?'订单、发货与安装':'我的订单与履约','付款、备货、配送、安装与售后共用订单记录。',go('继续选材','market'))+tabs('orders',['全部','待处理','已完成','异常与售后'])+table(['订单 / 商品','数量 / 单价','成交金额','交付','状态','操作'],list.map(o=>[o.id+'<small>'+esc(productBy(o.product)?.name)+'</small>',o.qty+' '+esc(productBy(o.product)?.unit)+'<small>¥'+money(o.price)+' / '+esc(productBy(o.product)?.unit)+'</small>','¥'+money(orderTotal(o))+'<small>含示例配送 ¥'+o.shipping+'</small>',esc(o.vendor)+'<small>'+esc(o.scheduled)+'</small>',badge(o.state),`<div class="row-actions">${eb('详情与下一步','order-detail',o.id)}${eb('联系相关方','order-chat',o.id)}${eb('售后','ticket-new',o.id)}</div>`]));}
function orderDetail(id){let o=E.orders.find(o=>o.id===id);if(!o)return;let p=productBy(o.product);let btns=[];if(!o.accepted&&can('supplier','company'))btns.push(eb('确认接单','order-transition',id,'accept'));if(o.state==='待付款'&&can('owner','company'))btns.push(primary('模拟付款确认','order-transition',id,'pay'));if(o.custom&&!o.measure&&can('supplier','designer','company'))btns.push(eb('复尺确认','order-transition',id,'measure'));if(o.custom&&!o.drawing&&can('owner','designer','company'))btns.push(eb('定制图纸确认','order-transition',id,'drawing'));if(['备货中','待复尺'].includes(o.state)&&can('supplier','company'))btns.push(eb(o.custom?'开始生产':'完成备货','order-transition',id,'prepare'));if(o.state==='生产中'&&can('supplier','company'))btns.push(eb('生产完成','order-transition',id,'produced'));if(o.state==='待发货'&&can('supplier','company'))btns.push(eb('登记发货','order-dispatch',id));if(o.state==='配送中'&&can('supplier','company'))btns.push(eb('登记送达','order-transition',id,'arrive'));if(['待签收','配送中'].includes(o.state)&&can('owner','builder','company'))btns.push(eb('核对收货','order-receive',id));if(o.state==='待安装'&&can('supplier','builder','company'))btns.push(eb('安装完成','order-transition',id,'install'));if(o.state==='待验收'&&can('owner','company'))btns.push(primary('确认订单验收','order-transition',id,'finish'));modal('订单 '+o.id,`<h3>${esc(p?.name)}</h3><div class="state-steps">${ORDER_STEPS.map(s=>`<span class="${o.state===s?'current':''}">${s}</span>`).join('')}</div>${detailCells({'当前状态':o.state,'数量 / 单价':o.qty+' '+p?.unit+' / ¥'+o.price,'订单金额':'¥'+money(orderTotal(o)),'商家':o.vendor,'收货房间':o.room,'送货计划':o.scheduled,'安装':o.installation,'采购类型':o.custom?'定制：复尺与图纸确认后生产':'现货或常规供货','接单确认':o.accepted?'已确认':'待供货方确认','付款':o.payment?'已模拟确认':'未确认','复尺 / 图纸':(o.measure?'已复尺':'待复尺')+' / '+(o.drawing?'图纸已确认':'图纸待确认')})}<div class="button-row">${btns.join('')}${can('supplier','company')&&!['完成','已取消','配送中','待签收','待验收','待安装'].includes(o.state)?eb('提出材料替换','replacement-new',o.id):''}${eb('上传凭证','order-evidence',id)}${eb('异常 / 退换','ticket-new',id)}</div><div class="action-group-title">履约记录</div>${(o.log||[]).map(l=>`<p class="subtext">${esc(l.time)} · ${esc(l.role)} · ${esc(l.text)}</p>`).join('')||'<p class="subtext">尚无新增履约记录。</p>'}${evidence(o.evidence)}<div class="notice">模拟交易，不会支付、发货或联系真实人员。实际收货应核对型号、数量、批次、破损及附件。</div>`,true);}
function renderContracts(){return moduleIntro('AGREEMENTS WITH A TRACE','合同与履约约定','范本、修改、双向确认和附件版本。原型确认不是电子签署。',can('designer','supplier','builder','company','inspector')?primary('＋ 生成合同草稿','contract-new'):'')+table(['合同','范围 / 金额','状态 / 版本','确认','操作'],projectRows('contracts').map(c=>[esc(c.title),esc(c.scope)+'<small>¥'+money(c.amount)+'</small>',badge(c.state)+'<small>V'+c.version+'</small>',(c.ownerConfirmed?'业主 ✓':'业主待确认')+'<small>'+(c.providerConfirmed?'服务方 ✓':'服务方待确认')+'</small>',`<div class="row-actions">${eb('条款与附件','contract-view',c.id)}${eb('检查缺项','contract-check',c.id)}${can('owner','designer','supplier','builder','company','inspector')?eb('确认本方约定','contract-confirm',c.id):''}${eb('下载草稿','contract-download',c.id)}${can('company','designer','supplier','builder','inspector')?eb(c.state==='已确认'?'发起补充协议':'修改草稿','contract-edit',c.id):''}</div>`]))+`<div class="notice">法务提示仅核对字段完整性，未接入法律审核模型。真实签约需采用正式电子签约或线下流程。</div>`;}
function contractView(id){let c=E.contracts.find(c=>c.id===id);modal(c.title,detailCells({'类型':c.kind,'总金额':'¥'+money(c.amount),'范围':c.scope,'未包含项':c.excludes,'付款条件':c.payTerms,'状态 / 版本':c.state+' / V'+c.version,'附件':c.attachments.join('、'),'双方确认':(c.ownerConfirmed?'业主已确认':'业主待确认')+'；'+(c.providerConfirmed?'服务方已确认':'服务方待确认')})+`<div class="rule-block">服务主体、实际范围、工期、验收标准、变更、质保和争议条款应在正式签约前明确。\n所有修改需双方重新确认；旧版本保留，不静默替换。\n正式附件：${esc(c.attachments.join(' / '))}</div><div class="button-row">${eb('检查缺项','contract-check',id)}${eb('确认本方约定','contract-confirm',id)}${eb('下载文本','contract-download',id)}</div><h3 style="margin-top:20px">修改历史</h3>${(c.revisions||[]).map(r=>`<p class="subtext">V${r.version} · ¥${money(r.amount)} · ${esc(r.scope)}</p>`).join('')||'<p class="subtext">暂无修改。</p>'}`,true);}
function paymentReady(m){let c=contractReady(m.contract),t=!m.task||E.tasks.find(t=>t.id===m.task)?.state==='完成';return {ready:c&&t,reason:!c?'合同双方尚未确认':!t?'履约或验收节点尚未完成':'付款条件已满足'};}
function renderPayments(embedded=false){return (embedded?'':moduleIntro('PAYMENT FOLLOWS PERFORMANCE','付款与阶段结算','合同、履约条件和验收记录关联。所有付款均为模拟，无资金流动。'))+table(['节点','对应合同 / 条件','金额','状态','操作'],projectRows('milestones').map(m=>{let r=paymentReady(m);return [esc(m.name),m.contract+'<small>'+esc(r.reason)+'</small>','¥'+money(m.amount),badge(m.paid?'已模拟支付':r.ready?'待付款':'未解锁'),`<div class="row-actions">${eb('查看条件','payment-view',m.id)}${can('owner','company')&&!m.paid?eb('模拟付款','payment-confirm',m.id):''}${m.paid?eb('下载记录','payment-download',m.id):''}</div>`];}))+`<div class="panel" style="margin-top:20px"><h3>对账与结算申请</h3><p class="subtext">材料、施工、设计和监理按各自单据申请；有争议的金额单独列出。</p><div class="button-row" style="margin-top:15px">${eb('发起对账','reconcile-new')}${eb('申请结算','settlement-new')}${eb('提出费用异议','fee-dispute')}</div></div>`;}
function renderChanges(){return moduleIntro('CHANGE, BEFORE WORK','增减项，先看影响再决定','保留原内容、差额、工期和确认链。未经确认不更新执行计划。',primary('＋ 发起变更','change-new'))+table(['变更','费用 / 工期','状态','影响与责任','操作'],projectRows('changes').map(c=>[esc(c.title)+'<small>'+esc(c.reason)+'</small>',(c.amount>=0?'+':'')+'¥'+money(c.amount)+'<small>'+c.days+' 天</small>',badge(c.state),esc(c.affects)+'<small>'+(c.emergency?'紧急事项：先记录保障措施，费用仍待确认':'常规确认流程')+'</small>',`<div class="row-actions">${eb('差异与记录','change-view',c.id)}${can('designer','builder','company')&&c.state==='待专业核实'?eb('完成专业核实','change-review',c.id):''}${can('owner')&&c.state==='待业主确认'?eb('确认并执行','change-approve',c.id):''}${can('owner')&&c.state==='待业主确认'?eb('不同意','change-reject',c.id):''}${!['已执行','已拒绝','已撤回'].includes(c.state)?eb('撤回','change-withdraw',c.id):''}</div>`]))+`<div class="module-banner" style="margin-top:20px"><div><h3>材料缺货或规格调整？</h3><p>使用材料替换流程，保留原商品、新商品、差价与交期差异。</p></div>${go('材料替换','replacements')}</div>`;}
function renderReplacements(){return moduleIntro('THE SAME PLAN, TRACKABLE CHANGES','材料替换，全程有据','供货方提出，设计与施工核实，业主确认后同步订单、清单和通知。',go('从订单提出替换','orders'))+table(['订单 / 商品','替代品','差价 / 交期','确认状态','操作'],projectRows('replacements').map(r=>[r.order+'<small>'+esc(productBy(r.old)?.name)+'</small>',esc(productBy(r.next)?.name),'¥'+money(r.delta)+'<small>'+r.days+' 天变化</small>',badge(r.state)+'<small>设计 '+(r.designer?'✓':'待核实')+' / 施工 '+(r.builder?'✓':'待核实')+'</small>',`<div class="row-actions">${eb('查看差异','replacement-view',r.id)}${can('designer','builder')&&r.state==='待相关方核实'?eb('确认本方影响','replacement-review',r.id):''}${can('owner')&&r.state==='待业主确认'?eb('同意替换','replacement-approve',r.id):''}${can('owner')&&r.state==='待业主确认'?eb('拒绝','replacement-reject',r.id):''}</div>`]));}
function taskBoard(){return `<div class="board">${['待开始','进行中','待验收','完成'].map(status=>`<section class="board-column"><h3>${status}</h3>${projectRows('tasks').filter(t=>t.state===status).slice(0,8).map(t=>`<div class="board-task"><h4>${esc(t.name)}</h4><p>${esc(t.person)} · ${t.days} 天</p><p>${taskReady(t)?'前序已满足':'等待前序节点'}</p><button class="text-button" data-eco="task-detail" data-id="${t.id}">查看与处理 →</button></div>`).join('')}</section>`).join('')}</div>`;}
function renderSchedule(){let tab=UI.tabs.schedule||'工序清单',tasks=projectRows('tasks');if(can('inspector')&&!UI.tabs.schedule)tab='上门日历';return moduleIntro('EVERY STEP, IN THE RIGHT ORDER',can('inspector')?'检查预约与上门日历':'施工计划与 SOP','前置、触发、人员、材料和验收共同决定工序。自动草案需专业确认发布。',can('company','builder','designer')?eb('从模板生成草案','sop-template')+primary('＋ 新建节点','task-new'):'')+tabs('schedule',['工序清单','任务看板','七天日历','上门日历'])+(tab==='任务看板'?taskBoard():tab==='七天日历'?`<div class="calendar-grid">${Array.from({length:14},(_,i)=>{let day=14+i,s='2026-11-'+day;return `<div class="calendar-day"><strong>11 月 ${day} 日</strong>${tasks.filter(t=>t.start<=s&&t.end>=s).map(t=>`<button class="calendar-event" data-eco="task-detail" data-id="${t.id}">${esc(t.name)}<br>${esc(t.person)}</button>`).join('')}</div>`}).join('')}</div>`:tab==='上门日历'?table(['检查','房间','预约日','状态','操作'],projectRows('checks').map(c=>[c.stage,esc(c.room),c.date,badge(c.state),eb('改约','check-appointment',c.id)])):table(['节点','前置 / 资源','时间','负责人','状态','操作'],tasks.map(t=>[esc(t.name)+'<small>'+esc(t.room)+'</small>',t.depends.map(id=>esc(E.tasks.find(x=>x.id===id)?.name||'已移除')).join('、')||'无前置',esc(t.start)+' → '+esc(t.end)+'<small>'+t.days+' 天</small>',esc(t.person),badge(!taskReady(t)&&t.state==='待开始'?'阻塞':t.state),`<div class="row-actions">${eb('详情与处理','task-detail',t.id)}${can('builder','company','designer')?eb('顺序与依赖','task-edit',t.id):''}</div>`])));}
function renderCrew(){let trade=UI.tabs.crew||'全部',list=E.crew.filter(p=>trade==='全部'||p.trade===trade);return moduleIntro('PEOPLE MAKE THE WORK HAPPEN','工人、班组与进场安排','按工种、日期和项目调配。冲突提示与变更记录一起保留。',primary('＋ 分配工人','crew-assign'))+tabs('crew',['全部',...C.trades])+table(['工人 / 工种','当前项目','日期 / 工时','状态','操作'],list.map(p=>[esc(p.name)+'<small>'+p.trade+'</small>',esc(E.projects.find(pr=>pr.id===p.project)?.name||'待分配'),p.date+'<small>'+p.hours+' 小时</small>',badge(p.state),`<div class="row-actions">${eb('安排与调班','crew-edit',p.id)}${eb(p.state==='暂停接单'?'恢复可预约':'暂停接单','crew-pause',p.id)}${eb('报到进场','crew-arrive',p.id)}</div>`]));}
function checkTable(){return table(['阶段 / 房间','检查日期','问题 / 证据','结果','操作'],projectRows('checks').map(c=>[c.stage+'<small>'+esc(c.room)+'</small>',c.date,c.issues.length+' 个问题 / '+c.evidence.length+' 份证据',badge(c.state),`<div class="row-actions">${eb('检查记录','check-detail',c.id)}${can('builder','company')&&c.state==='需整改'?eb('提交整改与复验','check-rectify',c.id):''}${eb('查看报告','check-report',c.id)}</div>`]));}
function renderQuality(){return moduleIntro('EVIDENCE BEFORE CONCLUSIONS',can('inspector')?'检查、整改与复验':'质量验收与问题整改','按约定清单记录，缺失项不自动通过。隐蔽检查通过后才解锁后续覆盖。',can('inspector','company','builder')?primary('＋ 新建检查','check-new'):'')+metrics([['待检查',projectRows('checks').filter(c=>c.state==='待检查').length,'核实资料'],['需整改',projectRows('checks').filter(c=>c.state==='需整改').length,'明确责任与期限'],['待复验',projectRows('checks').filter(c=>c.state==='待复验').length,'核对整改证据'],['已通过',projectRows('checks').filter(c=>c.state==='通过').length,'保留结论依据']])+checkTable()+`<div class="panel" style="margin-top:20px"><h3>检查标准与专业边界</h3><p class="subtext">检查依据来自项目约定及适用标准。此版提供结构化记录，不基于照片自动判定工程全部合格。</p>${go('标准与模板','standards')}</div>`;}
function renderCustomer(){let tab=UI.tabs.customer||'售后工单';return moduleIntro('SOMEONE IS HERE TO HELP','售后与客服，始终有回应','关联房间、订单和工程，先排查、再明确责任与费用。',primary('＋ 发起报修 / 售后','ticket-new'))+`<div class="service-center-cards"><button data-eco="customer-tab" data-value="在线客服"><strong>☏</strong>联系负责人<small>平台、商家与项目人员</small></button><button data-eco="ticket-new" data-value="商品质量"><strong>▣</strong>商品退换维修<small>破损、少件、错发与质量</small></button><button data-eco="ticket-new" data-value="施工质量"><strong>⌂</strong>工程问题报修<small>渗漏、墙面、安装与设备</small></button><button data-eco="customer-tab" data-value="质保档案"><strong>✓</strong>质保与记录<small>责任、期限和历史处理</small></button></div>`+tabs('customer',['售后工单','在线客服','质保档案','帮助与争议'])+(tab==='在线客服'?renderChat(true):tab==='质保档案'?table(['对象','交付状态','质保约定','历史售后','操作'],projectRows('orders').map(o=>[esc(productBy(o.product)?.name),badge(o.state),esc(productBy(o.product)?.warranty||'待确认'),E.tickets.filter(t=>t.order===o.id).length+' 次',eb('报修','ticket-new',o.id)])):tab==='帮助与争议'?`<div class="panel"><h2>问题由谁组织处理</h2><p class="subtext">主要交付责任方：${esc(currentProject().main)}。设计、材料和施工分别承担约定职责；平台协调并保留证据。</p><div class="object-list" style="margin-top:16px">${[['费用为什么增加','changes'],['商品型号或交期变化','replacements'],['验收与整改依据','quality'],['合同范围与未包含项','contracts']].map(([n,r])=>`<button class="single-source-link" data-route="${r}">${n}<span>→</span></button>`).join('')}</div><div class="notice">紧急问题先采取必要的现场保障措施并联系专业人员，同时登记问题；不在聊天中自动授权危险作业或额外收费。</div></div>`:table(['工单','关联','负责人 / 预约','状态','操作'],projectRows('tickets').map(t=>[esc(t.subject)+'<small>'+esc(t.kind)+'</small>',esc(t.room)+'<small>'+esc(t.order||'项目工程')+'</small>',esc(t.assigned)+'<small>'+esc(t.appointment||'尚未预约')+'</small>',badge(t.state)+(t.disputed?'<small>已申请平台协调</small>':''),`<div class="row-actions">${eb('处理进度','ticket-view',t.id)}${eb('补充证据','ticket-evidence',t.id)}${can('owner')?eb('催办','ticket-remind',t.id):''}</div>`])));}
function ticketDetail(id){let t=E.tickets.find(t=>t.id===id);if(!t)return;let btn=[];if(can('company','supplier','builder','admin')){btn.push(eb('分派与改约','ticket-assign',id));if(!['已完成','待确认'].includes(t.state))btn.push(eb('提交处理结果','ticket-result',id));}if(can('owner')){if(t.state==='待确认')btn.push(primary('确认解决','ticket-resolve',id));if(t.state==='已完成')btn.push(eb('问题未解决，重新打开','ticket-reopen',id));btn.push(eb('申请复议 / 平台介入','ticket-escalate',id));}modal(t.subject,detailCells({'问题类型':t.kind,'房间':t.room,'关联订单':t.order||'工程问题','状态':t.state,'处理负责人':t.assigned,'预约':t.appointment||'待安排','质保 / 收费':t.fee||'先核实责任及质保，收费需说明确认','复议':t.disputed?'已申请平台介入':'未申请'})+`<div class="button-row">${btn.join('')}${eb('补充说明','ticket-message',id)}${eb('上传证据','ticket-evidence',id)}</div><div class="chat-messages">${t.messages.map(m=>`<div class="chat-message ${m.role===state.role?'own':''}"><small>${roles[m.role]?.name||esc(m.role)} · ${esc(m.time.slice(0,16))}</small>${esc(m.text)}</div>`).join('')}</div>${evidence(t.evidence)}`,true);}
function renderChat(customer=false){let channel=UI.chat||'项目群',messages=E.chat.filter(m=>m.project===E.activeProject&&(m.channel||'项目群')===channel);return `<div class="chat-layout"><aside class="chat-list">${['项目群','主要承接方','设计师','材料商','施工负责人','平台协调'].map(c=>`<button class="chat-thread ${c===channel?'active':''}" data-eco="chat-channel" data-value="${c}"><b>${c}</b><small>${c==='项目群'?'关联任务、方案与问题':'项目服务沟通'}</small></button>`).join('')}</aside><section class="chat-main"><div class="section-head"><h3>${esc(channel)}</h3><span class="pill purple">本地协作演示</span></div><div class="chat-messages">${messages.map(m=>`<div class="chat-message ${m.role===state.role?'own':''}"><small>${roles[m.role]?.name||m.role} · ${esc(m.time.slice(0,16))}</small>${esc(m.text)}${m.ref?'<small>关联：'+esc(m.ref)+'</small>':''}<div class="button-row" style="margin-top:7px">${eb('转为任务','message-to-task',m.id)}${eb('生成问题工单','message-to-ticket',m.id)}</div></div>`).join('')||'<div class="small-empty">此会话还没有消息。发送后可切换身份演示协作回复。</div>'}</div><form id="eco-chat" class="chat-composer"><textarea name="text" required maxlength="1500" placeholder="说明问题；正式确认请到方案、合同或变更页面" aria-label="消息内容"></textarea><div><select name="ref" aria-label="关联业务"><option value="">关联业务（可选）</option>${projectRows('orders').map(o=>`<option>${esc(o.id+' '+productBy(o.product)?.name)}</option>`).join('')}${projectRows('designs').map(d=>`<option>${esc(d.name)}</option>`).join('')}</select><button class="primary compact" type="submit" style="margin-top:8px">发送本地消息</button></div></form><p class="component-note" style="margin-top:12px">未接入真实客服、外部消息或即时通讯；不会自动生成伪装人工的回复。</p></section></div>`;}
function renderMessages(){let tab=UI.tabs.messages||'通知';return moduleIntro('CONTEXT MAKES COMMUNICATION CLEAR','消息、任务与服务问题','每条关键消息可以关联项目对象。正式确认使用独立流程。',eb(E.notificationsMuted?'开启普通提醒':'汇总普通提醒','notification-toggle'))+tabs('messages',can('company','admin')?['通知','项目沟通','服务问题识别']:['通知','项目沟通'])+(tab==='项目沟通'?renderChat(false):tab==='服务问题识别'?renderSentiment():`<div class="panel">${E.messages.filter(m=>m.project===E.activeProject&&m.roles.includes(state.role)).map(m=>`<div class="event-item"><div><b>${esc(m.text)}</b><small>${esc(m.time.slice(0,16))} · ${m.read.includes(state.role)?'已读':'未读'}</small></div><div class="button-row">${eb('标记已读','message-read',m.id)}${go('打开关联',m.link)}</div></div>`).join('')||'<div class="small-empty">暂无当前角色的项目通知。</div>'}</div>`);}
function renderSentiment(){const flags=E.chat.filter(m=>m.project===E.activeProject&&/延期|漏水|投诉|加价|没解决|破损|催|负面|抖音/.test(m.text));return `<div class="notice">当前使用透明的关键词规则整理服务问题，未接入真实企业微信群或情绪模型。重点定位未解决事项，不给客户贴情绪标签。</div>`+table(['原始问题','分类提示','关联','操作'],flags.map(m=>[esc(m.text),/漏水|破损/.test(m.text)?'质量 / 售后':'交期 / 费用 / 服务',esc(m.ref||'当前项目'),eb('转为处理工单','message-to-ticket',m.id)]));}
function renderServices(){let items=E.services.filter(s=>s.role===state.role||can('company','admin'));if(can('inspector')&&!items.length)items=[{id:'monitor-package',name:'分项检查与复验服务',price:680,unit:'次',days:2,changes:1,state:'展示中',deliverable:'检查记录、问题清单、约定范围内复验及报告',role:'inspector'}];return moduleIntro('SELL A SERVICE, DEFINE THE DELIVERY',can('designer')?'设计服务与案例':can('inspector')?'监理服务与范围':'服务与案例管理','服务商品明确交付物、修改次数、周期和未包含项。',primary('＋ 发布服务','service-new'))+tabs('services',['服务套餐','案例与交付说明'])+(UI.tabs.services==='案例与交付说明'?`<div class="panel"><h2>案例资料</h2><p class="subtext">上传有权展示的真实案例，区分效果图与实景；可同时记录设计、代采或销售身份，以及实际售后主体。</p>${eb('上传案例资料','case-new')}${go('查看已上传资料','documents')}</div>`:`<div class="work-grid">${items.map(s=>`<article class="work-card"><div class="work-card-body"><div class="summary-title"><h3>${esc(s.name)}</h3>${badge(s.state)}</div><p>${esc(s.deliverable)}</p>${detailCells({'参考价':'¥'+s.price+' / '+s.unit,'交付周期':s.days+' 天','修改 / 复验':s.changes+' 次','销售主体':roles[s.role]?.name||s.role})}<div class="button-row">${eb('修改服务范围','service-edit',s.id)}${eb('暂停 / 恢复','service-toggle',s.id)}${eb('登记咨询','service-consult',s.id)}</div></div></article>`).join('')}</div>`);}
function renderInventory(){let q=UI.stockQuery,list=products.filter(p=>!q||(p.name+p.sku+p.vendor+p.sub).includes(q));let page=Number(UI.tabs.stockPage)||1;page=Math.min(page,Math.max(1,Math.ceil(list.length/15)));return moduleIntro('GOODS THAT CAN ACTUALLY BE DELIVERED',can('admin')?'商品资料治理':'商品、SKU 与库存','规格、包装、批次和交期可维护；示例资料不等于真实认证。',eb('批量导入 JSON','inventory-import')+primary('＋ 新增商品','product-edit'))+`<div class="module-search"><form id="inventory-search"><input name="q" value="${esc(q)}" placeholder="搜索名称、SKU、门店" aria-label="搜索库存"><button class="outline compact">搜索</button></form>${eb('导入格式示例','inventory-schema')}${eb('导出当前商品','inventory-export')}</div>`+table(['SKU / 商品','规格 / 供货方','价格 / 库存','交期 / 状态','操作'],list.slice((page-1)*15,page*15).map(p=>[p.sku+'<small>'+esc(p.name)+'</small>',esc(p.spec)+'<small>'+esc(p.vendor)+' · 批次 '+esc(p.batch)+'</small>','¥'+money(p.price)+' / '+p.unit+'<small class="'+(p.stock===0?'inventory-low':'')+'">库存 '+p.stock+' '+p.unit+'</small>',p.delivery+' 天<br>'+badge(p.status),`<div class="row-actions">${eb('编辑资料','product-edit',p.id)}${eb('库存 / 交期','stock-edit',p.id)}${eb(p.status==='上架'?'下架':'上架','product-status',p.id)}${eb('停产','product-discontinue',p.id)}${eb('关联模型资料','product-model',p.id)}</div>`]))+pagination(list.length,page,'stock-page',15);}
function renderQuotes(){let tab=UI.tabs.quotes||'询价单';return moduleIntro('CLEAR TERMS BEFORE A QUOTE','询价与供货报价','报价绑定规格、数量、交付条件及有效期。',primary('＋ 发起询价','custom-inquiry'))+tabs('quotes',['询价单','报价条件'])+(tab==='报价条件'?`<div class="panel"><h2>供货报价条件</h2><div class="check-list">${['采购主体与适用对象','规格与批次','数量和计价单位','包装换算及整箱规则','加工、配送、搬运、安装','报价有效期','售后与余料处理'].map(t=>`<label><input type="checkbox"> ${t}</label>`).join('')}</div>${go('报价进入合同约定','contracts')}</div>`:table(['询价商品','需求','报价 / 有效期','状态','操作'],projectRows('inquiries').map(q=>[esc(productBy(q.product)?.name||q.name||'自定义需求'),q.qty+' '+esc(productBy(q.product)?.unit||'项')+' / '+esc(q.room)+'<small>'+esc(q.note)+'</small>',q.price!==null?'¥'+money(q.price)+'<small>'+q.expires+'</small>':'待供货方报价',badge(q.state),`<div class="row-actions">${can('supplier','company')?eb('提交 / 修改报价','inquiry-respond',q.id):''}${q.price!==null&&can('owner','designer','builder','company')?eb('接受为采购参考','inquiry-accept',q.id):''}${eb('查看需求','inquiry-detail',q.id)}</div>`])));}
function renderPromotion(){return moduleIntro('RELEVANT REACH, CLEARLY LABELLED','推广中心','广告独立标识、区域和交期先筛选，不改变用户标签或验收结论。',can('supplier','company')?primary('＋ 创建推广','ad-new'):'')+table(['推广 / 商品','地区 / 场景','预算 / 时间','状态','操作'],E.ads.map(a=>[esc(a.name)+'<small>'+esc(productBy(a.product)?.name)+'</small>',a.area+' / '+esc(a.scene),'¥'+a.budget+'<small>'+a.start+' — '+a.end+'</small>',badge(a.state),`<div class="row-actions">${eb('预览与说明','ad-preview',a.id)}${can('supplier','company')&&a.state!=='已通过'?eb('提交审核','ad-submit',a.id):''}${can('admin')&&a.state==='待审核'?eb('通过','ad-approve',a.id):''}${['已通过','暂停'].includes(a.state)?eb(a.state==='暂停'?'恢复':'暂停','ad-toggle',a.id):''}${eb('调整预算','ad-edit',a.id)}</div>`]))+`<div class="panel" style="margin-top:20px"><h3>用户广告控制</h3><label class="toggle">使用个性化广告依据<input id="eco-ad-personalized" type="checkbox" ${E.adPersonalized?'checked':''}></label><p class="subtext">即使关闭，仍按主动提供的城市和适用条件筛选。商家只获得汇总信息。</p></div>`;}
function renderLeads(){return moduleIntro('FROM A QUESTION TO A PROJECT',can('designer')?'客户需求与设计咨询':'线索与客户管理','记录来源、需求、跟进和责任人。已有客户也可进入项目协作。',eb('批量导入 JSON','lead-import')+primary('＋ 新增客户','lead-new'))+table(['客户','来源 / 需求','预算 / 负责人','阶段','操作'],E.leads.map(l=>[esc(l.name),esc(l.source)+'<small>'+esc(l.scope)+'</small>','¥'+money(l.budget)+'<small>'+esc(l.owner)+'</small>',badge(l.state),`<div class="row-actions">${eb('分配与跟进','lead-edit',l.id)}${eb('预约量房','lead-measure',l.id)}${eb('转为项目','lead-convert',l.id)}${eb('查看记录','lead-view',l.id)}</div>`]));}
function renderFinance(){return moduleIntro('OPERATIONS WITH AN ACCOUNT','企业财务与结算','应收、应付、对账、费用和凭证按业务记录关联。',eb('发起对账','reconcile-new')+primary('登记费用 / 凭证','finance-new'))+metrics([['订单示例金额','¥'+money(projectRows('orders').reduce((s,o)=>s+orderTotal(o),0)),'同一交易金额一致'],['已模拟付款','¥'+money(paidTotal()),'无真实资金流动'],['已约定服务报酬','¥'+money(projectRows('remuneration').filter(r=>r.state==='已约定').reduce((s,r)=>s+r.amount,0)),'按合同与交付'],['未结工单',pendingWork().tickets,'争议费用独立核实']])+renderPayments(true)+`<div class="section-head" style="margin-top:25px"><h2>财务申请与记录</h2></div>${table(['业务','说明','时间'],state.requests.filter(r=>/结算|对账|费用|凭证|退款/.test(r.type)).map(r=>[esc(r.type),esc(r.text),new Date(r.time).toLocaleDateString('zh-CN')]))}`;}
function renderAnalytics(){let events=state.events.filter(e=>!e.retracted),paid=projectRows('orders').filter(o=>o.payment).length;return moduleIntro('MEASURE WHAT REALLY HAPPENED','经营与推荐分析','只汇总本浏览器实际体验记录；示例订单与真实行为分开说明。',eb('导出分析快照','analytics-export'))+metrics([['有效学习事件',events.length,'撤销事件不计入'],['确认偏好',confirmedTags().length,'可解释与纠正'],['当前项目选品',state.selected.length,'未等同于真实成交'],['已付款示例订单',paid,'包含预置演示数据']])+`<div class="two-cols"><section class="panel"><h2>本地行为分布</h2><div class="progress-chart">${[['收藏','favorite'],['方案选用','select'],['明确喜欢','positive'],['明确否认','negative'],['标签确认','confirm']].map(([label,kind])=>{let n=events.filter(e=>e.kind===kind).length;return `<div class="chart-row"><span>${label}</span><div class="bar"><i style="width:${events.length?n/events.length*100:0}%"></i></div><b>${n}</b></div>`}).join('')}</div></section><section class="panel"><h2>推荐策略版本</h2>${detailCells({'版本':'V'+E.strategy.version,'探索概率':Math.round(E.strategy.epsilon*100)+'%','训练模式':'本地在线学习与撤销重放','评估状态':'未进行真实线上对照试验'})}${can('admin')?eb('调整探索策略','strategy-edit')+eb('回退上一策略','strategy-rollback'):go('查看偏好与反馈','preferences')}</section></div><div class="notice">本地数据不能证明商业转化提升。真实上线需补充可见曝光、延迟反馈、对照组与交付指标。</div>`;}
function applicationTable(){return table(['主体','类型','审核状态','操作'],E.applications.map(a=>[esc(a.name),esc(a.type),badge(a.state),`<div class="row-actions">${eb('查看资料','application-view',a.id)}${can('admin')?eb('通过','application-state',a.id,'已通过')+eb('退回补充','application-state',a.id,'待补充'):''}</div>`]));}
function renderGovernance(){return moduleIntro('A FAIR ECOSYSTEM NEEDS RULES','平台审核与治理','入驻、资料、交易和售后按角色职责处理。此为运营界面演示。',primary('＋ 入驻申请','application-new'))+tabs('governance',['入驻审核','商品资料','广告审核','投诉协调','权限审计'])+((UI.tabs.governance||'入驻审核')==='入驻审核'?applicationTable():UI.tabs.governance==='商品资料'?`<div class="panel"><h3>商品资料核验</h3><p class="subtext">示例资料不含真实检测证照；字段完整不等于已通过真实认证。</p>${go('商品资料与停产管理','inventory')}</div>`:UI.tabs.governance==='广告审核'?renderPromotion():UI.tabs.governance==='投诉协调'?`<div class="panel"><h3>申请平台协调的事项</h3>${table(['问题','状态','负责人','操作'],E.tickets.filter(t=>t.disputed).map(t=>[esc(t.subject),badge(t.state),esc(t.assigned),eb('证据与进度','ticket-view',t.id)]))}</div>`:renderHistory(true));}
function renderStandards(){return moduleIntro('STANDARDS THAT CAN BE FOLLOWED','标准与模板版本','维护设计交付、施工工序、检查和合同核对项。',can('admin','company')?primary('＋ 新建规则','rule-new'):'')+table(['标准','版本','状态','内容','操作'],E.rules.map(r=>[esc(r.name),'V'+r.version,badge(r.state),esc(r.content),`<div class="row-actions">${eb('查看依据','rule-view',r.id)}${can('admin','company')?eb('修改新版本','rule-edit',r.id)+eb('发布','rule-publish',r.id):''}</div>`]))+`<div class="panel" style="margin-top:20px"><h3>SOP 模板目录</h3><div class="tags">${Object.keys(C.sop).map(t=>`<span class="tag">${t} · ${C.sop[t].length} 个节点</span>`).join('')}</div>${go('模板编排与确认发布','schedule')}</div>`;}
function renderHistory(embedded=false){let logs=E.audits.filter(a=>a.project===E.activeProject);return (embedded?'':moduleIntro('EVERY IMPORTANT ACTION LEAVES A TRACE','项目操作历史','角色、时间、对象和变更原因可追溯。历史不替代真实身份审计。',eb('导出历史','history-export')))+table(['时间','角色','操作','说明'],logs.slice().reverse().slice(0,100).map(a=>[new Date(a.time).toLocaleString('zh-CN'),roles[a.role]?.name||a.role,esc(a.type),esc(a.text)]));}
let ecoFormJob=null;
function field(key,label,type='text',options=[],extra={}){return {key,label,type,options,required:!['file','checkbox'].includes(type),...extra};}
function openForm(title,fields,values,submit,note='保存至当前浏览器的项目记录；不会向外部发送。'){
 ecoFormJob={fields,submit};
 const controls=fields.map(f=>{
  const value=values?.[f.key]??f.default??'';
  const attrs=`name="${esc(f.key)}" ${f.required?'required':''} ${f.min!==undefined?'min="'+f.min+'"':''} ${f.max!==undefined?'max="'+f.max+'"':''} ${f.type==='number'?'step="any"':''}`;
  let html;
  if(f.type==='select')html=`<select ${attrs} ${f.multiple?'multiple size="4"':''}>${f.options.map(o=>{const v=typeof o==='object'?o.value:o,label=typeof o==='object'?o.label:o;const selected=Array.isArray(value)?value.includes(v):String(v)===String(value);return `<option value="${esc(v)}" ${selected?'selected':''}>${esc(label)}</option>`;}).join('')}</select>`;
  else if(f.type==='textarea')html=`<textarea ${attrs} maxlength="3000">${esc(value)}</textarea>`;
  else if(f.type==='checkbox')html=`<input type="checkbox" ${attrs} ${value?'checked':''}>`;
  else if(f.type==='file')html=`<input type="file" ${attrs} accept="${f.accept||'image/*,.pdf,.json,.txt'}">`;
  else html=`<input type="${f.type}" ${attrs} value="${esc(value)}" maxlength="${f.maxlength||200}" ${f.placeholder?'placeholder="'+esc(f.placeholder)+'"':''}>`;
  return `<label class="field ${f.wide?'wide-field':''} ${f.type==='checkbox'?'checkbox-field':''} ${f.type==='file'?'upload-field':''}">${esc(f.label)}${html}${f.hint?'<small class="field-note">'+esc(f.hint)+'</small>':''}</label>`;
 }).join('');
 modal(title,`<p class="subtext">${note}</p><form id="eco-form"><div class="form-grid">${controls}</div><button type="submit" class="primary full-width">保存并更新记录</button></form>`);
}
function fileData(file){return new Promise((resolve,reject)=>{if(!file||!file.size)return resolve(null);if(file.size>500*1024)return reject(Error('单个文件请控制在 500 KB 内；大文件需接入文件服务'));if(file.type==='image/svg+xml'||/\.(html|js|svg)$/i.test(file.name))return reject(Error('请使用普通图片、PDF、JSON 或文本资料'));let r=new FileReader();r.onload=()=>{if(JSON.stringify(state).length+String(r.result).length>3800000)return reject(Error('本地资料较多，请先导出并改用较小文件'));resolve({name:file.name,data:r.result,date:TODAY});};r.onerror=()=>reject(Error('文件读取失败，请重试'));r.readAsDataURL(file);});}
function commit(msg='已保存并更新相关记录',opts={}){persist();closeModal();if(opts.render!==false)render();toast(msg);}
function addRequest(type,text){state.requests.push({type,text,time:Date.now()});audit(type,text);}
