function openTaskForm(t){let choices=projectRows('tasks').filter(x=>x.id!==t?.id&&!['已拆分','已合并'].includes(x.state));openForm(t?'调整节点与依赖':'新增施工节点',[field('name','节点名称'),field('person','负责人'),field('owner','负责角色','select',['designer','builder','inspector','company','supplier'].map(k=>({value:k,label:roles[k].name}))),field('room','房间','select',['全屋',...optionsRooms()]),field('start','开始日期','date'),field('end','结束日期','date'),field('days','预计工时天数','number',[],{min:.1,max:365}),field('predecessors','前置节点（可多选）','select',choices.map(x=>({value:x.id,label:x.name})),{required:false,multiple:true}),field('orderDeps','必须到场的材料订单（可多选）','select',projectRows('orders').map(o=>({value:o.id,label:o.id+' '+productBy(o.product)?.name})),{required:false,multiple:true}),field('materials','材料与进场条件'),field('standard','工艺与检查依据'),field('notes','协同、触发条件与说明','textarea',[],{wide:true,required:false})],t?{...t,predecessors:t.depends,orderDeps:t.orderDeps||[]}:{owner:'builder',room:'全屋',start:TODAY,end:'2026-11-16',days:2,materials:'相关材料需到场核实',standard:'以合同及确认图纸为依据'},d=>{if(d.end<d.start){toast('结束不能早于开始');return false;}if(t&&['完成','已拆分','已合并'].includes(t.state)){toast('已完成或归档节点不能直接修改');return false;}let depends=d.predecessors||[];if(t&&hasTaskCycle(t.id,depends)){toast('不能形成循环依赖');return false;}delete d.predecessors;if(t)Object.assign(t,d,{depends});else E.tasks.push({id:uid('task'),project:E.activeProject,...d,depends,state:'草案',draft:true,evidence:[]});audit('施工节点',d.name+' · 待核对计划');});}
function openCrewForm(c){openForm('人员排班与调配',[field('project','分配项目','select',[{value:'',label:'暂不分配'},...optionsProject()],{required:false}),field('date','进场日期','date'),field('hours','计划工时','number',[],{min:.5,max:12}),field('state','状态','select',['可预约','已安排','施工中','暂停接单'])],c,d=>{if(d.project&&c.project&&c.project!==d.project&&['施工中','已进场'].includes(c.state)){toast('该人员仍在其他工地，先完成移交或调整原排班');return false;}Object.assign(c,d);audit('排班调整',c.name+' · '+d.date);});}
function showCheck(id){let c=E.checks.find(c=>c.id===id);modal(c.stage+' · 检查清单',`<p class="subtext">${esc(c.room)} · ${c.date} · ${c.state}。结果由监理记录，施工方提交整改。</p>${table(['检查项','当前结果','依据 / 实测','操作'],(C.checklists[c.stage]||[]).map(k=>[k,c.values[k]?badge(c.values[k].result):badge('待核实'),esc(c.values[k]?.note||'未记录'),can('inspector')?eb('记录实测','check-item',c.id,k):'待监理记录']))}${evidence(c.evidence)}<div class="button-row">${eb('上传证据','check-evidence',id)}${can('inspector')?primary('确认检查通过','check-pass',id):''}${can('builder','company')&&c.state==='需整改'?eb('提交整改','check-rectify',id):''}${eb('查看报告','check-report',id)}</div><div class="notice">通过前需所有适用检查项记录为符合并保留依据及证据；无法检查或待专项检测不能自动通过。</div>`,true);}
