/* Preserve the original learner, but score once per candidate and keep real policy traces. */
rank=function(list,log=true){if(!state.personalized||!state.modelOn||sort!=='recommend')return [...list];let model=fitModel(),remaining=list.map(p=>({p,s:score(p,model)})),out=[],trace=[],counts={};const eps=E.strategy.epsilon;while(remaining.length){let best=0,bestScore=-Infinity;remaining.forEach((x,i)=>{let s=x.s-.08*(counts[x.p.cat]||0);if(s>bestScore){bestScore=s;best=i;}});let exploring=Math.random()<eps,index=exploring?Math.floor(Math.random()*remaining.length):best;let item=remaining[index].p;trace.push({id:item.id,p:eps/remaining.length+(index===best?1-eps:0),explore:exploring,score:remaining[index].s});out.push({...item,explore:exploring});counts[item.cat]=(counts[item.cat]||0)+1;remaining.splice(index,1);}if(log){state.impressions.push({id:uid('batch'),time:Date.now(),project:E.activeProject,room:roomFilter,category,trace:trace.slice(0,48),modelVersion:state.events.filter(e=>!e.retracted).length,policyVersion:E.strategy.version});state.impressions=state.impressions.slice(-60);persist();}return out;};
const baseScore=score;
score=function(p,model){let x=features(p);let value=x.reduce((s,v,i)=>s+v*model.theta[i],0),conf=Math.sqrt(Math.max(0,x.reduce((s,v,i)=>s+v*model.A[i].reduce((a,b,j)=>a+b*x[j],0),0)));let tags=confirmedTags();return value+.15*conf+.12*p.tags.filter(t=>tags.includes(t)).length;};
